def academic_discontinuation_is_fail(apps, schema_editor):
    """Every "discontinued" standing so far came from results (GPA below 2.0, a
    repeat failed): it is FAIL now. "Discontinued" is kept for the Principal's
    disciplinary decision (said 19 October 2026). The date each standing began
    is taken from its last change, so the two-year rules have a start."""
    StudentStanding = apps.get_model('attendance', 'StudentStanding')
    StudentStanding.objects.filter(status='discontinued').update(status='failed')
    for standing in StudentStanding.objects.filter(since__isnull=True):
        StudentStanding.objects.filter(pk=standing.pk).update(since=standing.updated_at.date())


def fail_is_discontinued_again(apps, schema_editor):
    StudentStanding = apps.get_model('attendance', 'StudentStanding')
    StudentStanding.objects.filter(status='failed').update(status='discontinued')


